FUNCTIONS = {
    0xEC0E: ('InitializeTextWindow', 'Сброс курсоров очереди и настройка тридцати строк стековой прокрутки'),
    0xECA2: ('ConsumeTextQueue', 'Вывод очередного числа либо символа активной строки текстовой очереди'),
    0xECF3: ('PrintByteDecimal', 'Десятичный вывод байта с минимальной шириной два знака'),
    0xED28: ('ScrollTextWindow', 'Перенос пяти рядов текста вверх через SP и очистка нижнего ряда'),
    0xEFC4: ('PrintTextGlyph', 'Подготовка вывода знака 4 на 6 пикселей с проверкой правой границы'),
    0xEFF1: ('DrawGlyphRows', 'Слияние шести строк упакованного знака с выбранной тетрадой экрана')}
LOCAL = {
    0xEC2E: 'PatchRow', 0xEC51: 'NextScan',
    0xECAE: 'ReadItem', 0xECC9: 'FreeOrEnd', 0xECD1: 'UseString', 0xECD2: 'ReadCharacter',
    0xECE2: 'FinishString', 0xECE9: 'NewLine',
    0xECFC: 'CountHundreds', 0xED0A: 'PrintLastTwo', 0xED14: 'CountTens', 0xED1B: 'EmitTens',
    0xEFE3: 'SetDestination', 0xEFF9: 'SelectFontHalf', 0xF001: 'SelectRotation', 0xF059: 'DirectRows'}
LABELS = {('Controls', address): name for address, name in LOCAL.items()}
RENAMES = {}
for address, (name, _) in FUNCTIONS.items():
    RENAMES['Controls.Unknown'+format(address, '04X')+'.Entry'] = 'Controls.'+name+'.Entry'
    end = next((a for a in sorted(FUNCTIONS) if a > address), 0xF094)
    for point, label in LOCAL.items():
        if address <= point < end:
            RENAMES['Controls.Unknown'+format(address, '04X')+'.Point'+format(point, '04X')] = 'Controls.'+name+'.'+label

